tr.addEventListener('pointerdown',function(e){if(e.pointerType!=='mouse')return;down=true;mv=0;sx=e.clientX;sl=tr.scrollLeft;tr.classList.add('drag')});
addEventListener('pointermove',function(e){if(!down)return;mv=Math.max(mv,Math.abs(e.clientX-sx));tr.scrollLeft=sl-(e.clientX-sx)});
